#!/usr/bin/env python3
"""Atomically snapshot Linux per-process descriptor occupancy candidates."""
import datetime
import errno
import json
import os
import re
import time
import uuid

PROC = "/proc"
SPOOL_DIR = "/var/lib/splunk-process-fd/spool"
SCHEMA_VERSION = 1
CANDIDATE_FLOOR_PCT = 50.0
LIMIT_RE = re.compile(r"^Max open files\s+(\S+)\s+(\S+)\s+(\S+)\s*$")


def utc(epoch):
    return datetime.datetime.fromtimestamp(epoch, datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def read_stat(pid):
    with open(f"{PROC}/{pid}/stat", "r", encoding="utf-8") as handle:
        raw = handle.read().strip()
    left = raw.find("(")
    right = raw.rfind(")")
    if left < 1 or right <= left or right + 2 >= len(raw):
        raise ValueError("malformed proc stat")
    fields = raw[right + 2 :].split()
    if len(fields) < 20:
        raise ValueError("short proc stat")
    return raw[left + 1 : right], int(fields[19])


def parse_limit(value):
    if value == "unlimited":
        return "unlimited", None
    parsed = int(value)
    if parsed < 0:
        raise ValueError("negative RLIMIT_NOFILE")
    return "finite", parsed


def read_nofile_limits(pid):
    with open(f"{PROC}/{pid}/limits", "r", encoding="utf-8") as handle:
        for line in handle:
            match = LIMIT_RE.match(line.rstrip("\n"))
            if match:
                soft_status, soft = parse_limit(match.group(1))
                hard_status, hard = parse_limit(match.group(2))
                return soft_status, soft, hard_status, hard
    raise ValueError("Max open files row missing")


def classify_os_error(error):
    if error.errno in (errno.ENOENT, errno.ESRCH):
        return "race"
    if error.errno in (errno.EACCES, errno.EPERM):
        return "permission"
    return "error"


def main():
    os.umask(0o027)
    started = int(time.time())
    scan_id = str(uuid.uuid4())
    with open(f"{PROC}/sys/kernel/random/boot_id", "r", encoding="ascii") as handle:
        boot_id = handle.read().strip().lower()
    if not re.fullmatch(r"[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}", boot_id):
        raise ValueError("invalid boot_id")
    base = {"schema_version": SCHEMA_VERSION, "scan_id": scan_id, "scan_epoch": started, "boot_id": boot_id}
    os.makedirs(SPOOL_DIR, mode=0o750, exist_ok=True)
    temporary = os.path.join(SPOOL_DIR, f".{scan_id}.tmp")
    final = os.path.join(SPOOL_DIR, f"{scan_id}.ndjson")
    scanned = finite = emitted = races = permission_errors = collection_errors = 0
    output = os.fdopen(os.open(temporary, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_CLOEXEC | os.O_NOFOLLOW, 0o640), "w", encoding="utf-8")
    try:
        pids = sorted(int(name) for name in os.listdir(PROC) if name.isdigit())
        for pid in pids:
            try:
                comm, start_ticks = read_stat(pid)
                soft_status, soft, hard_status, hard = read_nofile_limits(pid)
                with os.scandir(f"{PROC}/{pid}/fd") as entries:
                    fd_numbers = [int(entry.name) for entry in entries if entry.name.isdigit()]
                process_uid = os.stat(f"{PROC}/{pid}", follow_symlinks=False).st_uid
                try:
                    executable = os.readlink(f"{PROC}/{pid}/exe")
                except OSError as error:
                    if classify_os_error(error) == "permission":
                        executable = None
                    elif error.errno == errno.ENOENT:
                        executable = None
                    else:
                        raise
                comm_after, start_ticks_after = read_stat(pid)
                if start_ticks != start_ticks_after or comm != comm_after:
                    races += 1
                    continue
                scanned += 1
                if soft_status == "finite":
                    finite += 1
                    usage_pct = 100.0 * len(fd_numbers) / soft if soft and soft > 0 else None
                    at_or_above = sum(1 for descriptor in fd_numbers if soft is not None and descriptor >= soft)
                else:
                    usage_pct = None
                    at_or_above = 0
                if usage_pct is None or (usage_pct < CANDIDATE_FLOOR_PCT and at_or_above == 0):
                    continue
                observed = int(time.time())
                event = dict(base)
                event.update({"event_time": utc(observed), "record_type": "process", "observed_epoch": observed, "pid": pid, "starttime_ticks": start_ticks, "process_instance_id": f"{boot_id}:{pid}:{start_ticks}", "process_uid": process_uid, "comm": comm, "exe": executable, "open_fd_count": len(fd_numbers), "highest_fd_number": max(fd_numbers) if fd_numbers else None, "fds_at_or_above_soft_limit": at_or_above, "soft_limit_status": soft_status, "soft_limit_nofile": soft, "hard_limit_status": hard_status, "hard_limit_nofile": hard})
                output.write(json.dumps(event, separators=(",", ":"), sort_keys=True) + "\n")
                emitted += 1
            except OSError as error:
                kind = classify_os_error(error)
                if kind == "race":
                    races += 1
                elif kind == "permission":
                    permission_errors += 1
                else:
                    collection_errors += 1
            except (ValueError, OverflowError):
                collection_errors += 1
        completed = int(time.time())
        status = "ok" if permission_errors == 0 and collection_errors == 0 else "partial"
        manifest = dict(base)
        manifest.update({"event_time": utc(completed), "record_type": "scan_complete", "completed_epoch": completed, "duration_seconds": completed - started, "collector_status": status, "candidate_floor_pct": CANDIDATE_FLOOR_PCT, "process_count": scanned, "finite_limit_process_count": finite, "emitted_process_count": emitted, "process_race_count": races, "permission_error_count": permission_errors, "collection_error_count": collection_errors})
        output.write(json.dumps(manifest, separators=(",", ":"), sort_keys=True) + "\n")
        output.flush()
        os.fsync(output.fileno())
        output.close()
        os.replace(temporary, final)
        directory = os.open(SPOOL_DIR, os.O_RDONLY | os.O_DIRECTORY)
        try:
            os.fsync(directory)
        finally:
            os.close(directory)
    except Exception:
        output.close()
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return 0 if permission_errors == 0 and collection_errors == 0 else 2


if __name__ == "__main__":
    raise SystemExit(main())
